"""Official spectrum presets, fan PWM mapping, and power safety limits for Netlea 7-series 90W."""

from __future__ import annotations

from dataclasses import dataclass

FAN_GEAR_TO_PWM: tuple[int, ...] = (0, 120, 130, 145, 165, 180, 200, 220, 230, 240, 250)
ATMOS_GEAR_TO_PWM: tuple[int, ...] = (0, 20, 38, 70, 140, 245)

MAX_TOTAL_POWER_W = 91
FAN_SAFETY_POWER_THRESHOLD_W = 20
MIN_SAFE_FAN_GEAR = 1
MIN_SAFE_FAN_PWM = FAN_GEAR_TO_PWM[MIN_SAFE_FAN_GEAR]


@dataclass(frozen=True, slots=True)
class PresetGrade:
    """Single brightness grade within a spectrum preset (R, W, G, B, fan_gear, power_w)."""

    red: int
    white: int
    green: int
    blue: int
    fan_gear: int
    power_w: int

    @property
    def fan_pwm(self) -> int:
        return fan_gear_to_pwm(self.fan_gear)


