def normalize_model_family(model: str | None) -> str:
    """Return canonical preset family ('N7-90' or '7S-90') for a device model string."""
    text = str(model or "").upper()
    if "7S" in text:
        return "7S-90"
    return "N7-90"


def presets_for_model(model: str | None) -> dict[str, dict[int, tuple[int, int, int, int, int, int]]]:
    """Return preset table for the given Netlea 90W model."""
    return S7_90_PRESETS if normalize_model_family(model) == "7S-90" else N7_90_PRESETS


def preset_names_for_model(model: str | None) -> list[str]:
    """Return ordered preset names for the given model."""
    return list(presets_for_model(model).keys())


def get_preset_grade(model: str | None, preset_name: str, grade: int) -> PresetGrade | None:
    """Look up a specific preset and grade (clamped to valid range)."""
    table = presets_for_model(model)
    grades = table.get(preset_name)
    if not grades:
        return None
    min_g, max_g = min(grades), max(grades)
    clamped = max(min_g, min(int(grade), max_g))
    r, w, g, b, f_gear, p_w = grades[clamped]
    return PresetGrade(red=r, white=w, green=g, blue=b, fan_gear=f_gear, power_w=p_w)


def match_preset_from_channels(model: str | None, r: int, w: int, g: int, b: int) -> tuple[str, int] | None:
    """Return (preset_name, grade) if (R, W, G, B) exactly matches a known preset grade."""
    for pname, grades in presets_for_model(model).items():
        for grade, vals in grades.items():
            if vals[0] == r and vals[1] == w and vals[2] == g and vals[3] == b:
                return pname, grade
    return None


def fan_gear_to_pwm(gear: int) -> int:
    """Convert fan gear 0..10 into hardware PWM byte (0, 120..250)."""
    idx = max(0, min(int(gear), len(FAN_GEAR_TO_PWM) - 1))
    return FAN_GEAR_TO_PWM[idx]


def fan_pwm_to_gear(pwm: int) -> int:
    """Convert hardware fan PWM byte to nearest fan gear 0..10."""
    val = max(0, min(int(pwm), 255))
    if val == 0:
        return 0
    best_idx = 1
    best_diff = abs(FAN_GEAR_TO_PWM[1] - val)
    for idx in range(2, len(FAN_GEAR_TO_PWM)):
        diff = abs(FAN_GEAR_TO_PWM[idx] - val)
        if diff < best_diff:
            best_diff = diff
            best_idx = idx
    return best_idx


def atmos_gear_to_pwm(gear: int) -> int:
    """Convert atmosphere gear 0..5 to hardware PWM byte (0, 20, 38, 70, 140, 245)."""
    idx = max(0, min(int(gear), len(ATMOS_GEAR_TO_PWM) - 1))
    return ATMOS_GEAR_TO_PWM[idx]


def atmos_pwm_to_gear(pwm: int) -> int:
    """Convert atmosphere hardware PWM byte to nearest gear 0..5."""
    val = max(0, min(int(pwm), 255))
    if val == 0:
        return 0
    best_idx = 1
    best_diff = abs(ATMOS_GEAR_TO_PWM[1] - val)
    for idx in range(2, len(ATMOS_GEAR_TO_PWM)):
        diff = abs(ATMOS_GEAR_TO_PWM[idx] - val)
        if diff < best_diff:
            best_diff = diff
            best_idx = idx
    return best_idx


def _channel_power_w(channel: str, pwm: int) -> int:
    val = max(0, min(int(pwm), 255))
    if val == 0:
        return 0
    curve = CHANNEL_CURVES.get(channel)
    if not curve:
        return 0
    # Find closest PWM point on official channel curve
    best_w = curve[-1][1]
    best_diff = 9999
    for c_pwm, c_w in curve:
        diff = abs(c_pwm - val)
        if diff < best_diff:
            best_diff = diff
            best_w = c_w
    return best_w


def estimate_power_w(r: int, w: int, g: int, b: int, fan_pwm: int = 0) -> int:
    """Estimate total single-lamp power in watts using official Netlea formula."""
    ch_pwms = (('R', r), ('W', w), ('G', g), ('B', b))
    active = sum(1 for _, v in ch_pwms if v > 0)
    led_w = sum(_channel_power_w(ch, v) for ch, v in ch_pwms)
    fan_gear = fan_pwm_to_gear(fan_pwm)
    fan_w = 0
    if fan_gear > 0 and 'F' in CHANNEL_CURVES:
        f_curve = CHANNEL_CURVES['F']
        fan_w = f_curve[min(fan_gear, len(f_curve) - 1)][1]
    total = led_w + fan_w - max(0, active - 1)
    return max(0, total)


def percent_to_channel_pwm(channel: str, percent: float) -> int:
    """Convert 0..100% slider to official channel PWM using cSpectrums curve."""
    curve = CHANNEL_CURVES.get(channel)
    if not curve:
        return max(0, min(255, round(percent * 2.55)))
    pct = max(0.0, min(100.0, float(percent)))
    idx = round((pct / 100.0) * (len(curve) - 1))
    return curve[idx][0]


def channel_pwm_to_percent(channel: str, pwm: int) -> float:
    """Convert hardware channel PWM to approximate 0..100% slider value."""
    curve = CHANNEL_CURVES.get(channel)
    if not curve or len(curve) <= 1:
        return round(max(0, min(255, int(pwm))) / 2.55, 1)
    val = max(0, min(255, int(pwm)))
    if val == 0:
        return 0.0
    best_idx = min(range(len(curve)), key=lambda i: abs(curve[i][0] - val))
    return round(best_idx * 100.0 / (len(curve) - 1), 1)


def enforce_power_and_fan_safety(
    r: int, w: int, g: int, b: int, fan_pwm: int | None = None
) -> tuple[int, int, int, int, int]:
    """Scale down RGBW if estimated power > 91W and enforce non-zero fan above 20W."""
    r = max(0, min(255, int(r)))
    w = max(0, min(255, int(w)))
    g = max(0, min(255, int(g)))
    b = max(0, min(255, int(b)))
    # Auto-pick recommended fan PWM if omitted
    if fan_pwm is None:
        est = estimate_power_w(r, w, g, b, 0)
        if est <= 5:
            f_pwm = 0
        elif est <= 20:
            f_pwm = fan_gear_to_pwm(2)
        elif est <= 45:
            f_pwm = fan_gear_to_pwm(3)
        elif est <= 70:
            f_pwm = fan_gear_to_pwm(5)
        else:
            f_pwm = fan_gear_to_pwm(6)
    else:
        f_pwm = max(0, min(255, int(fan_pwm)))
        if 0 < f_pwm <= 10:
            # Defensive guard: legacy callers passing gear 1..10 get mapped to real PWM
            f_pwm = fan_gear_to_pwm(f_pwm)

    # Enforce 91W official power cap by proportional scaling
    for _ in range(12):
        est = estimate_power_w(r, w, g, b, f_pwm)
        if est <= MAX_TOTAL_POWER_W:
            break
        scale = (MAX_TOTAL_POWER_W - 2) / max(est, 1)
        r = int(r * scale)
        w = int(w * scale)
        g = int(g * scale)
        b = int(b * scale)

    # Hardware thermal protection: power > 20W forbids fan off
    if estimate_power_w(r, w, g, b, f_pwm) > FAN_SAFETY_POWER_THRESHOLD_W and f_pwm < MIN_SAFE_FAN_PWM:
        f_pwm = MIN_SAFE_FAN_PWM
    return r, w, g, b, f_pwm
